reference_css:
* { box-sizing: border-box; }
:root { color-scheme: light; --color-text: #172554; --color-surface: #fff; --color-muted: #475569; --color-border: #cbd5e1; --color-primary: #1d4ed8; --space: 1rem; --radius: .75rem; --elevation: 0 1rem 2rem rgb(15 23 42 / .08); }
body { margin: 0; font: 1rem/1.6 system-ui, sans-serif; color: var(--color-text); background: var(--color-surface); }
.site-header { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; padding: 1rem max(1rem, calc((100vw - 72rem) / 2)); border-bottom: 1px solid var(--color-border); }
.site-header nav { display: flex; gap: 1rem; flex-wrap: wrap; }
.brand { font-weight: 850; text-decoration: none; }
.page-shell { width: min(calc(100% - 2rem), 72rem); margin-inline: auto; }
.hero, .section { padding-block: clamp(2rem, 5vw, 4rem); }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1.1; max-width: 18ch; }
.token-grid, .component-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr)); gap: var(--space); }
.token-card, .card, .demo-form, .alert { padding: var(--space); border: 1px solid var(--color-border); border-radius: var(--radius); background: var(--color-surface); box-shadow: var(--elevation); }
.token-swatch { display: block; width: 100%; height: 3rem; border-radius: .4rem; background: var(--color-primary); }
.token-swatch--surface { background: var(--color-surface); border: 1px solid var(--color-border); }
.token-swatch--accent { background: #0f766e; }
.component-demo { display: flex; flex-wrap: wrap; gap: .75rem; }
.button { border: 2px solid var(--color-primary); border-radius: .5rem; padding: .65rem 1rem; background: var(--color-primary); color: white; font: inherit; font-weight: 700; }
.button-secondary { color: var(--color-primary); background: transparent; }
.button:disabled { opacity: .55; cursor: not-allowed; }
.demo-form { display: grid; gap: .5rem; max-width: 32rem; margin-block: 1rem; }
input { width: 100%; padding: .7rem; border: 1px solid var(--color-border); border-radius: .4rem; font: inherit; }
.helper-text { margin: 0; color: var(--color-muted); font-size: .875rem; }
.alert { border-inline-start: 4px solid #0f766e; margin-block: 1rem; }
[data-theme="dark"] { color-scheme: dark; --color-text: #e2e8f0; --color-surface: #0f172a; --color-muted: #cbd5e1; --color-border: #475569; --color-primary: #93c5fd; }
:focus-visible { outline: 3px solid #0f766e; outline-offset: 3px; }
@media (max-width: 38rem) { .site-header { padding-inline: 1rem; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }
